// G2Ball Football – web server (no dependencies, Node 18+).
// Serves the built website and a small JSON API:
//   accounts   – email + password sign-in (scrypt hashes, httpOnly session cookie)
//   favourites – up to 5 teams per account, including non-league Full-Time teams
//   fulltime   – FA Full-Time divisions, fetched with the G2Ball Apify actor using the
//                site owner's APIFY_TOKEN (server-side only) and cached on disk.
//
// Settings (environment variables):
//   PORT=8787                 HOST=0.0.0.0
//   DATA_DIR=./data           where accounts.json and divisions.json are kept (back this folder up)
//   APIFY_TOKEN=…             Apify API token (Console → Settings → API & Integrations). Required to add new divisions.
//   APIFY_ACTOR=…             optional: actor id or "username~g2ball-fulltime-feed" (found automatically if not set)
//   FULLTIME_API_URL=…        optional: your own FullTime API instance, tried before Apify
//   DIVISION_TTL_HOURS=6      how long a division's data is used before it is refreshed
//   NEW_DIVISIONS_PER_DAY=20  cap on brand-new divisions added per day (protects your Apify credit)
//   REFRESH_RUNS_PER_DAY=40   cap on background refresh runs per day
//   SIGNUPS_PER_HOUR=20       cap on new accounts per hour per IP address
//   TRUST_PROXY=1             set when running behind a reverse proxy/load balancer (Render, Railway, nginx)
import http from 'node:http';
import { promises as fs, createReadStream, existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

// Website files and seed data embedded below so this one file is the whole app.
const EMBED_DIST = {"index.html": "", "logo.png": "", "favicon.png": "", "glasses/04-match-next.png": "", "glasses/02-favourites-live.png": "", "glasses/01-home-live.png": "", "glasses/16-goal-alert.png": "", "assets/index-DCL4rEJu.css": "", "assets/index-a37bSwvX.js": ""};
const EMBED_SEED = "";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = HERE;
const env = process.env;
const PORT = +(env.PORT || 8787);
const HOST = env.HOST || '0.0.0.0';
const DATA_DIR = path.resolve(ROOT, env.DATA_DIR || 'data');
const STATIC_DIR = path.resolve(ROOT, env.STATIC_DIR || 'site');
const TTL = (+(env.DIVISION_TTL_HOURS || 6)) * 3600_000;
const NEW_PER_DAY = +(env.NEW_DIVISIONS_PER_DAY || 20);
const REFRESH_PER_DAY = +(env.REFRESH_RUNS_PER_DAY || 40);
const SIGNUPS_PER_HOUR = +(env.SIGNUPS_PER_HOUR || 20);
const TRUST_PROXY = env.TRUST_PROXY === '1' || env.TRUST_PROXY === 'true';
const MAX_FAVS = 5;

// ---------- single-file bundle: unpack the website and seed data on start ----------
{
  const { mkdirSync, writeFileSync } = await import('node:fs');
  if (!existsSync(path.join(STATIC_DIR, 'index.html'))) {
    for (const [rel, b64] of Object.entries(EMBED_DIST)) {
      const out = path.join(STATIC_DIR, rel);
      mkdirSync(path.dirname(out), { recursive: true });
      writeFileSync(out, Buffer.from(b64, 'base64'));
    }
    console.log(`Unpacked ${Object.keys(EMBED_DIST).length} website files to ${STATIC_DIR}`);
  }
  mkdirSync(DATA_DIR, { recursive: true });
  const seedPath = path.join(DATA_DIR, 'seed-divisions.json');
  if (!existsSync(seedPath)) writeFileSync(seedPath, Buffer.from(EMBED_SEED, 'base64'));
}
const SESSION_DAYS = 60;
const COOKIE = 'g2b_session';

// ---------- tiny JSON store (atomic writes) ----------
class Store {
  constructor(file, empty) { this.file = path.join(DATA_DIR, file); this.empty = empty; this.data = null; this.timer = null; this.writing = Promise.resolve(); }
  async load(seed) {
    await fs.mkdir(DATA_DIR, { recursive: true });
    try { this.data = JSON.parse(await fs.readFile(this.file, 'utf8')); }
    catch (e) {
      if (e.code !== 'ENOENT') throw new Error(`Can't read ${this.file}: ${e.message}`);
      this.data = seed ? seed() : structuredClone(this.empty);
      await this.flush();
    }
    return this;
  }
  save() { clearTimeout(this.timer); this.timer = setTimeout(() => void this.flush(), 300); }
  flush() {
    clearTimeout(this.timer);
    const body = JSON.stringify(this.data);
    this.writing = this.writing.then(async () => {
      const tmp = `${this.file}.${process.pid}.tmp`;
      await fs.writeFile(tmp, body, { mode: 0o600 });
      await fs.rename(tmp, this.file);
    }).catch((e) => console.error('save failed', this.file, e.message));
    return this.writing;
  }
}

const accounts = await new Store('accounts.json', { users: {}, sessions: {} }).load();
const divisions = await new Store('divisions.json', { divisions: {} }).load(() => {
  // First start: preload any divisions shipped in data/seed-divisions.json (an Apify feed record).
  const out = { divisions: {} };
  const seedFile = path.join(DATA_DIR, 'seed-divisions.json');
  if (existsSync(seedFile)) {
    try {
      const f = JSON.parse(readFileSync(seedFile, 'utf8'));
      for (const d of f.divisions ?? []) out.divisions[d.id] = { ...cleanDivision(d), updated: f.updated, source: 'seed', link: '' };
      console.log(`Seeded ${Object.keys(out.divisions).length} Full-Time divisions`);
    } catch (e) { console.warn('seed-divisions.json ignored:', e.message); }
  }
  return out;
});

// ---------- helpers ----------
const now = () => Date.now();
const sha = (s) => crypto.createHash('sha256').update(s).digest('hex');
const rid = (n = 16) => crypto.randomBytes(n).toString('hex');
const scrypt = (pw, salt) => new Promise((ok, no) => crypto.scrypt(pw, salt, 64, { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 }, (e, k) => (e ? no(e) : ok(k.toString('hex')))));
const normEmail = (e) => String(e ?? '').trim().toLowerCase();
const EMAIL_RE = /^[^\s@]{1,64}@[^\s@]{1,190}\.[^\s@]{2,24}$/;
const str = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');

function clientIp(req) {
  if (TRUST_PROXY) { const xf = String(req.headers['x-forwarded-for'] ?? '').split(',')[0].trim(); if (xf) return xf; }
  return req.socket.remoteAddress ?? '?';
}

// Fixed-window limiter: key → {n, reset}
const buckets = new Map();
function limited(key, max, windowMs) {
  const t = now(); const b = buckets.get(key);
  if (!b || b.reset < t) { buckets.set(key, { n: 1, reset: t + windowMs }); return false; }
  b.n++; return b.n > max;
}
setInterval(() => { const t = now(); for (const [k, b] of buckets) if (b.reset < t) buckets.delete(k); }, 60_000).unref();

function send(res, status, body, headers = {}) {
  const data = body === undefined ? '' : JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', ...headers });
  res.end(data);
}
const fail = (res, status, error, extra = {}) => send(res, status, { error, ...extra });

async function readJson(req, max = 16_384) {
  const ct = String(req.headers['content-type'] ?? '');
  if (!/^application\/json\b/i.test(ct)) throw Object.assign(new Error('Send JSON'), { status: 415 });
  let size = 0; const chunks = [];
  for await (const c of req) { size += c.length; if (size > max) throw Object.assign(new Error('Request too large'), { status: 413 }); chunks.push(c); }
  try { return JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}'); } catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}

function cookies(req) {
  const out = {};
  for (const part of String(req.headers.cookie ?? '').split(';')) { const i = part.indexOf('='); if (i > 0) out[part.slice(0, i).trim()] = decodeURIComponent(part.slice(i + 1).trim()); }
  return out;
}
function isHttps(req) { return req.socket.encrypted || (TRUST_PROXY && String(req.headers['x-forwarded-proto'] ?? '').split(',')[0].trim() === 'https'); }
function sessionCookie(req, token, maxAgeSec) {
  return `${COOKIE}=${token ? encodeURIComponent(token) : ''}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAgeSec}${isHttps(req) ? '; Secure' : ''}`;
}

// ---------- accounts ----------
function publicUser(u) { return { email: u.email, name: u.name || '', favourites: u.favourites ?? [], created: u.created }; }
function currentUser(req) {
  const auth = String(req.headers.authorization ?? '');
  const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : cookies(req)[COOKIE];
  if (!token || token.length > 200) return null;
  const s = accounts.data.sessions[sha(token)];
  if (!s || s.expires < now()) return null;
  const u = accounts.data.users[s.uid];
  if (!u) return null;
  if (s.expires - now() < (SESSION_DAYS - 7) * 864e5) { s.expires = now() + SESSION_DAYS * 864e5; accounts.save(); }  // sliding expiry
  return { user: u, tokenHash: sha(token) };
}
function newSession(uid) {
  const token = rid(32);
  accounts.data.sessions[sha(token)] = { uid, created: now(), expires: now() + SESSION_DAYS * 864e5 };
  accounts.save();
  return token;
}
setInterval(() => { let n = 0; for (const [k, s] of Object.entries(accounts.data.sessions)) if (s.expires < now()) { delete accounts.data.sessions[k]; n++; } if (n) accounts.save(); }, 3600_000).unref();

/** Validates one favourite from the browser. */
function cleanFav(f) {
  if (!f || typeof f !== 'object') return null;
  const src = f.src === 'ft' ? 'ft' : f.src === 'espn' ? 'espn' : null;
  if (!src) return null;
  const name = str(f.name, 80);
  if (!name) return null;
  if (src === 'espn') {
    const id = str(f.id, 40);
    if (!/^[\w.:-]{1,40}$/.test(id)) return null;
    const league = str(f.league, 40);
    return { src, id, name, league: /^[\w.-]{1,40}$/.test(league) ? league : undefined, leagueName: str(f.leagueName, 80) || undefined };
  }
  const div = str(f.div, 20);
  if (!/^\d{3,15}$/.test(div)) return null;
  const ftName = str(f.ftName, 80) || name;
  return { src, id: `ft:${div}:${ftName.toLowerCase()}`.slice(0, 120), div, name, ftName, leagueName: str(f.leagueName, 80) || undefined };
}

// ---------- FA Full-Time divisions ----------
function cleanDivision(d) {
  const arr = (a) => (Array.isArray(a) ? a.slice(0, 1500) : []);
  return { id: String(d.id), name: String(d.name ?? '').slice(0, 120), season: d.season ? String(d.season) : undefined, table: arr(d.table), fixtures: arr(d.fixtures), results: arr(d.results), errors: arr(d.errors).map(String).slice(0, 10) };
}

/** Accepts a Full-Time division link (table/fixtures/results page) or a bare division ID. */
function parseDivisionRef(ref) {
  const v = String(ref ?? '').trim();
  if (/^\d{3,15}$/.test(v)) return { id: v, link: `https://fulltime.thefa.com/table.html?selectedDivision=${v}` };
  let u; try { u = new URL(v); } catch { return null; }
  if (!/(^|\.)fulltime\.thefa\.com$/i.test(u.hostname) && !/(^|\.)full-time\.thefa\.com$/i.test(u.hostname)) return null;
  const id = u.searchParams.get('selectedDivision') ?? u.searchParams.get('divisionseason');
  if (!id || !/^\d{3,15}$/.test(id)) return null;
  const q = new URLSearchParams();
  for (const k of ['league', 'selectedSeason', 'selectedDivision', 'selectedCompetition', 'selectedFixtureGroupKey']) {
    const x = u.searchParams.get(k); if (x && /^[\w-]{1,30}$/.test(x)) q.set(k, x);
  }
  q.set('selectedDivision', id);
  return { id, link: `https://fulltime.thefa.com/table.html?${q}` };
}

const runs = new Map();      // divisionId → { started, promise, error? }
const dayKey = () => new Date().toISOString().slice(0, 10);
function quota(kind) {
  const q = (divisions.data.quota ??= {});
  if (q.day !== dayKey()) { q.day = dayKey(); q.new = 0; q.refresh = 0; }
  return q;
}

let actorId = env.APIFY_ACTOR || '';
async function apify(pathname, init = {}) {
  const r = await fetch(`https://api.apify.com/v2${pathname}`, { ...init, headers: { Authorization: `Bearer ${env.APIFY_TOKEN}`, 'Content-Type': 'application/json', ...(init.headers ?? {}) }, signal: AbortSignal.timeout(30_000) });
  const body = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(body?.error?.message ? `Apify: ${body.error.message}` : `Apify ${r.status}`);
  return body.data ?? body;
}
async function findActor() {
  if (actorId) return actorId;
  const list = await apify('/acts?my=true&limit=100');
  const hit = (list.items ?? []).find((a) => /g2ball.*full.?time|fulltime.*feed/i.test(`${a.name} ${a.title ?? ''}`));
  if (!hit) throw new Error('Apify: no G2Ball Full-Time actor found on this account. Set APIFY_ACTOR.');
  actorId = hit.id;
  console.log(`Using Apify actor ${hit.username}~${hit.name} (${hit.id})`);
  return actorId;
}

/** Optional: a FullTime API instance (github.com/jwhughes-work/FullTimeAPI). */
async function viaFullTimeApi(id) {
  const base = (env.FULLTIME_API_URL || '').replace(/\/+$/, '');
  if (!base) return null;
  const get = (p) => fetch(`${base}${p}`, { signal: AbortSignal.timeout(20_000) }).then((r) => (r.ok ? r.json() : Promise.reject(new Error(`FullTime API ${r.status}`))));
  const [table, fixtures, results] = await Promise.all([get(`/api/League/${id}`), get(`/api/Fixtures/${id}`).catch(() => []), get(`/api/Results/${id}`).catch(() => [])]);
  const rows = Array.isArray(table) ? table : table?.teams ?? table?.table ?? [];
  if (!rows.length) return null;
  return { id, name: '', table: rows, fixtures: Array.isArray(fixtures) ? fixtures : [], results: Array.isArray(results) ? results : [], errors: [], source: 'fulltime-api' };
}

async function viaApify(id, link) {
  if (!env.APIFY_TOKEN) throw new Error('This site has no Apify key set up yet, so new Full-Time divisions can\'t be added. Ask the site owner to set APIFY_TOKEN.');
  const actor = await findActor();
  const input = { startUrls: [{ url: link }], storeName: `g2ball-web-${id}` };
  const run = await apify(`/acts/${encodeURIComponent(actor)}/runs?timeout=600&memory=2048`, { method: 'POST', body: JSON.stringify(input) });
  const t0 = now();
  let status = run.status, runId = run.id;
  while (!['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT'].includes(status)) {
    if (now() - t0 > 11 * 60_000) throw new Error('Full-Time took too long to answer. Try again later.');
    await new Promise((r) => setTimeout(r, 8000));
    status = (await apify(`/actor-runs/${runId}`)).status;
  }
  const out = await fetch(`https://api.apify.com/v2/actor-runs/${runId}/key-value-store/records/OUTPUT`, { headers: { Authorization: `Bearer ${env.APIFY_TOKEN}` }, signal: AbortSignal.timeout(30_000) }).then((r) => (r.ok ? r.json() : null)).catch(() => null);
  const d = out?.divisions?.find((x) => String(x.id) === id) ?? out?.divisions?.[0];
  if (!d || (!d.table?.length && !d.fixtures?.length && !d.results?.length)) {
    throw new Error(status === 'SUCCEEDED' ? 'Full-Time returned no data for that division. Check the link opens a league table.' : 'Full-Time could not be reached just now. Try again later.');
  }
  return { ...d, source: 'apify' };
}

/** Starts (or joins) a fetch for one division. Resolves when the data is saved. */
function refreshDivision(id, link, reason) {
  const cur = runs.get(id);
  if (cur) return cur.promise;
  const entry = { started: now() };
  entry.promise = (async () => {
    try {
      const d = (await viaFullTimeApi(id).catch(() => null)) ?? (await viaApify(id, link));
      const prev = divisions.data.divisions[id];
      const clean = cleanDivision({ ...d, id });
      // Keep earlier good data if this run came back partly empty.
      if (prev) for (const k of ['table', 'fixtures', 'results']) if (!clean[k].length && prev[k]?.length) clean[k] = prev[k];
      divisions.data.divisions[id] = { ...clean, name: clean.name || prev?.name || '', updated: new Date().toISOString(), source: d.source, link };
      delete divisions.data.divisions[id].lastError;
      divisions.save();
      console.log(`Division ${id} ${reason}: ${clean.table.length} table rows, ${clean.fixtures.length} fixtures, ${clean.results.length} results`);
    } catch (e) {
      console.warn(`Division ${id} ${reason} failed: ${e.message}`);
      const prev = divisions.data.divisions[id];
      if (prev) { prev.lastError = e.message; divisions.save(); }
      else divisions.data.failed = { ...(divisions.data.failed ?? {}), [id]: { error: e.message, at: now() } };
      entry.error = e.message;
      throw e;
    } finally { setTimeout(() => runs.delete(id), entry.error ? 10 * 60_000 : 0); }
  })();
  entry.promise.catch(() => {});
  runs.set(id, entry);
  return entry.promise;
}

function divisionResponse(id) {
  const d = divisions.data.divisions[id];
  const run = runs.get(id);
  if (!d) return run?.error ? { status: 'error', error: run.error } : run ? { status: 'pending', started: run.started } : { status: 'missing' };
  const stale = now() - Date.parse(d.updated || 0) > TTL;
  return { status: 'ready', refreshing: !!run && !run.error, stale, division: d };
}

// Background refresh: divisions anyone follows, oldest first, within the daily cap.
async function backgroundRefresh() {
  const followed = new Set();
  for (const u of Object.values(accounts.data.users)) for (const f of u.favourites ?? []) if (f.src === 'ft') followed.add(f.div);
  const due = [...followed].map((id) => divisions.data.divisions[id]).filter((d) => d && d.link && now() - Date.parse(d.updated || 0) > TTL)
    .sort((a, b) => Date.parse(a.updated || 0) - Date.parse(b.updated || 0));
  for (const d of due) {
    const q = quota();
    if (q.refresh >= REFRESH_PER_DAY || !env.APIFY_TOKEN && !env.FULLTIME_API_URL) break;
    q.refresh++; divisions.save();
    await refreshDivision(d.id, d.link, 'refresh').catch(() => {});
  }
}
setInterval(() => void backgroundRefresh(), 30 * 60_000).unref();

// ---------- API ----------
async function api(req, res, url) {
  const p = url.pathname.replace(/^.*?\/api\//, '/');
  const m = req.method;
  // Writes need a JSON body and our header: blocks cross-site form posts (CSRF).
  if (m !== 'GET' && m !== 'HEAD' && req.headers['x-g2ball'] !== '1') return fail(res, 403, 'Missing request header');

  if (p === '/health' && m === 'GET') return send(res, 200, { ok: true, accounts: true, fulltime: !!(env.APIFY_TOKEN || env.FULLTIME_API_URL), version: '1.1' });

  if (p === '/auth/signup' && m === 'POST') {
    const ip = clientIp(req);
    if (limited(`su:${ip}`, SIGNUPS_PER_HOUR, 3600_000)) return fail(res, 429, 'Too many new accounts from here. Try again in an hour.');
    const b = await readJson(req);
    const email = normEmail(b.email), password = String(b.password ?? ''), name = str(b.name, 40);
    if (!EMAIL_RE.test(email)) return fail(res, 400, 'Enter a valid email address.');
    if (password.length < 8 || password.length > 200) return fail(res, 400, 'Use a password of at least 8 characters.');
    const uid = sha(`uid:${email}`).slice(0, 24);
    if (accounts.data.users[uid]) return fail(res, 409, 'There is already an account with that email. Sign in instead.');
    const salt = rid(16);
    const favourites = (Array.isArray(b.favourites) ? b.favourites : []).map(cleanFav).filter(Boolean).slice(0, MAX_FAVS);
    accounts.data.users[uid] = { uid, email, name, salt, hash: await scrypt(password, salt), created: new Date().toISOString(), favourites };
    const token = newSession(uid);
    return send(res, 201, { user: publicUser(accounts.data.users[uid]), token }, { 'Set-Cookie': sessionCookie(req, token, SESSION_DAYS * 86400) });
  }

  if (p === '/auth/login' && m === 'POST') {
    const ip = clientIp(req);
    const b = await readJson(req);
    const email = normEmail(b.email), password = String(b.password ?? '');
    if (limited(`li:${ip}`, 30, 15 * 60_000) || limited(`le:${email}`, 10, 15 * 60_000)) return fail(res, 429, 'Too many attempts. Wait 15 minutes and try again.');
    const u = accounts.data.users[sha(`uid:${email}`).slice(0, 24)];
    // Same work and same message whether or not the account exists.
    const h = await scrypt(password.slice(0, 200), u?.salt ?? 'no-such-user-salt');
    if (!u || !crypto.timingSafeEqual(Buffer.from(h, 'hex'), Buffer.from(u.hash, 'hex'))) return fail(res, 401, 'Email or password is wrong.');
    const token = newSession(u.uid);
    return send(res, 200, { user: publicUser(u), token }, { 'Set-Cookie': sessionCookie(req, token, SESSION_DAYS * 86400) });
  }

  if (p === '/auth/logout' && m === 'POST') {
    const me = currentUser(req);
    if (me) { delete accounts.data.sessions[me.tokenHash]; accounts.save(); }
    return send(res, 200, { ok: true }, { 'Set-Cookie': sessionCookie(req, '', 0) });
  }

  if (p === '/me' && m === 'GET') {
    const me = currentUser(req);
    return me ? send(res, 200, { user: publicUser(me.user) }) : fail(res, 401, 'Not signed in');
  }

  if (p === '/me' && m === 'DELETE') {
    const me = currentUser(req);
    if (!me) return fail(res, 401, 'Not signed in');
    for (const [k, s] of Object.entries(accounts.data.sessions)) if (s.uid === me.user.uid) delete accounts.data.sessions[k];
    delete accounts.data.users[me.user.uid];
    accounts.save();
    return send(res, 200, { ok: true }, { 'Set-Cookie': sessionCookie(req, '', 0) });
  }

  if (p === '/favourites' && m === 'PUT') {
    const me = currentUser(req);
    if (!me) return fail(res, 401, 'Sign in to save favourites.');
    const b = await readJson(req);
    const list = (Array.isArray(b.favourites) ? b.favourites : []).map(cleanFav).filter(Boolean);
    const seen = new Set(); const out = [];
    for (const f of list) { if (!seen.has(f.id)) { seen.add(f.id); out.push(f); } }
    if (out.length > MAX_FAVS) return fail(res, 400, `You can follow up to ${MAX_FAVS} teams.`);
    me.user.favourites = out; accounts.save();
    return send(res, 200, { favourites: out });
  }

  // GET /fulltime/division?ref=<link or id>      (ref lookups that need a new fetch require sign-in)
  // GET /fulltime/division/<id>                  (cached data only, public)
  if (p === '/fulltime/division' && m === 'GET') {
    const ref = parseDivisionRef(url.searchParams.get('ref'));
    if (!ref) return fail(res, 400, 'Paste a Full-Time division link (it contains selectedDivision=…) or the division ID number.');
    const r = divisionResponse(ref.id);
    if (r.status === 'ready' || r.status === 'pending') {
      if (r.status === 'ready' && r.stale && !runs.has(ref.id) && (env.APIFY_TOKEN || env.FULLTIME_API_URL)) {
        const q = quota(); if (q.refresh < REFRESH_PER_DAY) { q.refresh++; divisions.save(); void refreshDivision(ref.id, r.division.link || ref.link, 'refresh').catch(() => {}); r.refreshing = true; }
      }
      return send(res, 200, r);
    }
    const me = currentUser(req);
    if (!me) return fail(res, 401, 'Sign in to add a new Full-Time division.');
    if (limited(`nd:${me.user.uid}`, 5, 3600_000)) return fail(res, 429, 'You have added several new divisions in the last hour. Try again later.');
    const recent = divisions.data.failed?.[ref.id];
    if (recent && now() - recent.at < 15 * 60_000) return send(res, 200, { status: 'error', error: recent.error });
    if (!env.APIFY_TOKEN && !env.FULLTIME_API_URL) return send(res, 200, { status: 'error', error: 'This site has no Apify key set up yet, so new Full-Time divisions can\'t be added. Ask the site owner to set APIFY_TOKEN.' });
    const q = quota();
    if (q.new >= NEW_PER_DAY) return send(res, 200, { status: 'error', error: 'The daily limit for adding new divisions has been reached. Try again tomorrow.' });
    q.new++; divisions.save();
    void refreshDivision(ref.id, ref.link, `added by ${me.user.uid.slice(0, 6)}`).catch(() => {});
    return send(res, 202, { status: 'pending', started: now() });
  }
  const dm = /^\/fulltime\/division\/(\d{3,15})$/.exec(p);
  if (dm && m === 'GET') return send(res, 200, divisionResponse(dm[1]));

  return fail(res, 404, 'Not found');
}

// ---------- static files ----------
const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.json': 'application/json', '.txt': 'text/plain; charset=utf-8', '.webp': 'image/webp', '.woff2': 'font/woff2' };
async function serveStatic(req, res, url) {
  let rel = decodeURIComponent(url.pathname);
  if (rel.endsWith('/')) rel += 'index.html';
  const file = path.resolve(STATIC_DIR, `.${rel}`);
  if (!file.startsWith(STATIC_DIR + path.sep) && file !== STATIC_DIR) return fail(res, 403, 'Forbidden');
  if (/(^|[\\/])\.[^\\/]+/.test(path.relative(STATIC_DIR, file))) return fail(res, 404, 'Not found');
  let st; try { st = await fs.stat(file); } catch { st = null; }
  if (!st || !st.isFile()) {
    // Unknown path: send the app (pages use #/… links, so this only catches typos).
    if (!path.extname(rel)) return serveStatic(req, res, new URL('/', url));
    return fail(res, 404, 'Not found');
  }
  const ext = path.extname(file).toLowerCase();
  res.writeHead(200, {
    'Content-Type': TYPES[ext] ?? 'application/octet-stream', 'Content-Length': st.size,
    'Cache-Control': rel.startsWith('/assets/') ? 'public, max-age=31536000, immutable' : ext === '.html' ? 'no-cache' : 'public, max-age=3600',
  });
  if (req.method === 'HEAD') return res.end();
  createReadStream(file).pipe(res);
}

const SECURITY = {
  'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'strict-origin-when-cross-origin', 'X-Frame-Options': 'SAMEORIGIN',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
};
const server = http.createServer(async (req, res) => {
  for (const [k, v] of Object.entries(SECURITY)) res.setHeader(k, v);
  if (TRUST_PROXY && isHttps(req)) res.setHeader('Strict-Transport-Security', 'max-age=15552000');
  let url;
  try { url = new URL(req.url ?? '/', 'http://local'); } catch { return fail(res, 400, 'Bad request'); }
  try {
    if (/\/api\//.test(url.pathname)) return await api(req, res, url);
    if (req.method !== 'GET' && req.method !== 'HEAD') return fail(res, 405, 'Method not allowed');
    return await serveStatic(req, res, url);
  } catch (e) {
    if (!res.headersSent) fail(res, e.status ?? 500, e.status ? e.message : 'Something went wrong');
    if (!e.status) console.error(e);
  }
});
server.listen(PORT, HOST, () => {
  console.log(`G2Ball Football web on http://${HOST}:${PORT}  (data: ${DATA_DIR}, site: ${STATIC_DIR})`);
  console.log(`Full-Time: ${env.APIFY_TOKEN ? 'Apify key set' : 'no APIFY_TOKEN, so only cached divisions'}${env.FULLTIME_API_URL ? ' + FullTime API' : ''}`);
  setTimeout(() => void backgroundRefresh(), 20_000).unref();
});
const stop = async () => { await Promise.all([accounts.flush(), divisions.flush()]); process.exit(0); };
process.on('SIGTERM', stop); process.on('SIGINT', stop);
